Tested in Chrome Version 24.0.1312.52 m<p><pre><code>  var savedCount = 0;
  var saveFromDeathInterval = setInterval(function(){
  	for(var i=0;i<tabLemmings.length;i++){
            var lem = tabLemmings[i];
            if(lem.etat == 'tombe'){
               lem.etat = 'para';
               lem.paraOpen();
               savedCount++;
            }
  	}
        if(savedCount == 404)
        {
           clearInterval(saveFromDeathInterval);
        }
  },2000);</code></pre>
